// Generated by `just generate` from `src/plugins/dotclaude-codegraph/slices/graph/lab/tree-change.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `tool.call` hook of the `graph` slice: the sync of the index after a `git` command that changes the tree.
// The hook sits above the stub of the engine, and the stubs answer `process.run` and `fs.exists`.
// No `codegraph` runs, and no `git` command runs.

import type { On } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

/** Stubs for one test. The result lists the `process.run` argument lists and the `fs.exists` paths. */
const stub = (on: On, indexed = true, fails = false) => {
  const seen = { runs: [] as (readonly string[])[], checks: [] as string[] };
  on("tool.call", () => ({ result: "ok" }));
  mock.env(on, { CLAUDE_PROJECT_DIR: "/p" });
  on("fs.exists", (_$, e) => {
    seen.checks.push(String(e.path));
    return { value: indexed };
  });
  on("process.run", (_$, e) => {
    seen.runs.push(e.argv);
    if (fails) throw new Error("codegraph is missing");
    return {
      value: {
        exitCode: 0,
        stdout: "",
        stderr: "",
        isStdoutTruncated: false,
        isStderrTruncated: false,
      },
    };
  });
  return seen;
};

const bash = ($: Engine, command: string) =>
  $.tool.call({ tool: "Bash", command });

test("a `git commit` call syncs an indexed project", async ($: Engine, on: On) => {
  const seen = stub(on);
  const out = await bash($, "git commit -m x");
  expect(out.result).toBe("ok");
  expect(seen.runs).toStrictEqual([["codegraph", "sync", "-q"]]);
});

test("each `git` command that changes the tree syncs once", async ($: Engine, on: On) => {
  const seen = stub(on);
  for (const sub of [
    "merge main",
    "rebase main",
    "pull --ff-only",
    "checkout main",
    "switch main",
    "reset --hard HEAD~1",
    "cherry-pick abc",
    "revert abc",
    "stash pop",
    "apply a.patch",
    "am a.mbox",
  ])
    await bash($, `git ${sub}`);
  expect(seen.runs.length).toBe(11);
});

test("a `Bash` call of another command does not reach the hook", async ($: Engine, on: On) => {
  const seen = stub(on);
  for (const command of [
    "ls",
    "git status",
    "git diff HEAD",
    "git log --oneline",
    "git push",
  ])
    expect((await bash($, command)).result, command).toBe("ok");
  expect(seen.checks).toStrictEqual([]);
  expect(seen.runs).toStrictEqual([]);
});

test("a project with no index runs nothing", async ($: Engine, on: On) => {
  const seen = stub(on, false);
  expect((await bash($, "git commit -m x")).result).toBe("ok");
  expect(seen.runs).toStrictEqual([]);
});

test("a failed sync leaves the result of the call as it is", async ($: Engine, on: On) => {
  stub(on, true, true);
  expect((await bash($, "git merge main")).result).toBe("ok");
});
